func (r *retentionCompliancePolicyResource) refresh(ctx context.Context, identity string, m *retentionCompliancePolicyModel, diags *diag.Diagnostics, reflected func(map[string]any) bool) bool {
	get := func(ctx context.Context) (map[string]any, bool, error) {
		res, gerr := r.client.SCC.GetRetentionCompliancePolicy(ctx, purview.GetRetentionCompliancePolicyParams{Identity: identity})
		if gerr != nil {
			if isNotFound(gerr) {
				return nil, false, nil
			}
			return nil, false, gerr
		}
		o := firstObject(res.Value)
		return o, o != nil, nil
	}
	obj, present, err := resourcex.LoadUntil(ctx, consistency.Config{}, get, reflected)
	if err != nil {
		diags.AddError("Get-RetentionCompliancePolicy failed", err.Error())
		return false
	}
	if !present {
		return false
	}
	readRetentionCompliancePolicy(ctx, obj, m)
	return true
}

